draw:
var d = p.diam * 1e-10;
var n = p.dens * 1e25;
var lam = 1 / (Math.SQRT2 * Math.PI * d * d * n);
var vbar = p.speed;
var rate = vbar / lam;

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";

var pad = 22;
var x0 = pad, x1 = W - pad, y0 = 20, y1 = H - 34;
var yc = (y0 + y1) / 2;

var pxPerLam = (x1 - x0) / 5.0;
var tube = Math.max(6, Math.min(26, pxPerLam * 0.22));

ctx.strokeStyle = C.rule;
ctx.setLineDash([4, 4]);
ctx.beginPath(); ctx.moveTo(x0, yc - tube); ctx.lineTo(x1, yc - tube); ctx.stroke();
ctx.beginPath(); ctx.moveTo(x0, yc + tube); ctx.lineTo(x1, yc + tube); ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.figure;
ctx.fillText("swept tube of cross-section pi d squared", x0, y0 - 6);

ctx.strokeStyle = C.ink;
ctx.lineWidth = 1.5;
ctx.beginPath(); ctx.moveTo(x0, yc); ctx.lineTo(x1, yc); ctx.stroke();

var i;
for (i = 1; i <= 5; i++) {
  var hx = x0 + i * pxPerLam;
  if (hx > x1) { break; }
  ctx.fillStyle = C.figure;
  ctx.beginPath(); ctx.arc(hx, yc, 4, 0, Math.PI * 2); ctx.fill();
  ctx.strokeStyle = C.faint;
  ctx.lineWidth = 1;
  ctx.beginPath(); ctx.moveTo(hx, yc - tube); ctx.lineTo(hx, yc + tube); ctx.stroke();
}

var travel = (t * 0.9) % 5;
var mx = x0 + travel * pxPerLam;
if (mx < x1) {
  ctx.fillStyle = C.accent;
  ctx.beginPath(); ctx.arc(mx, yc, 5, 0, Math.PI * 2); ctx.fill();
}

ctx.strokeStyle = C.accent;
ctx.lineWidth = 1.5;
var ay = y1 + 4;
ctx.beginPath(); ctx.moveTo(x0, ay); ctx.lineTo(x0 + pxPerLam, ay); ctx.stroke();
ctx.beginPath(); ctx.moveTo(x0, ay - 4); ctx.lineTo(x0, ay + 4); ctx.stroke();
ctx.beginPath(); ctx.moveTo(x0 + pxPerLam, ay - 4); ctx.lineTo(x0 + pxPerLam, ay + 4); ctx.stroke();
ctx.fillStyle = C.ink;
ctx.fillText("one mean free path", x0 + 6, ay + 18);

out.note = "mean free path " + lam.toExponential(2) + " m, and at " + vbar.toFixed(0) + " m/s that is " + rate.toExponential(2) + " collisions per second";
